package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	wWeight := 0
	bWeight := 0

	scanner := bufio.NewScanner(os.Stdin)

	for i := 0; i < 8; i++ {
		if !scanner.Scan() {
			return
		}
		line := strings.TrimSpace(scanner.Text())

		for j := 0; j < 8 && j < len(line); j++ {
			switch line[j] {
			case 'Q':
				wWeight += 9
			case 'R':
				wWeight += 5
			case 'B', 'N':
				wWeight += 3
			case 'P':
				wWeight++
			case 'q':
				bWeight += 9
			case 'r':
				bWeight += 5
			case 'b', 'n':
				bWeight += 3
			case 'p':
				bWeight++
			}
		}
	}

	if wWeight > bWeight {
		fmt.Print("White")
	}
	if wWeight < bWeight {
		fmt.Print("Black")
	}
	if wWeight == bWeight {
		fmt.Print("Draw")
	}
}

